# "—" sınır metni olan araçlarda gösterilecek ortak cümle
NO_LIMIT = ("Bilinen özel bir sınırı yok; sonuçlar telefonun donanımına bağlıdır.",
            "No special limitation known; results depend on the phone's hardware.")

INFO = {
 "level": ("Telefonun ivmeölçeriyle (varsa yerçekimi sensörüyle) yerçekiminin yönünü ölçer. Telefon yüzeye yatırıldığında iki eksenli kabarcık, kenarı üstünde dik durduğunda tek açı gösterir; kip kendiliğinden değişir.\n\nEğim yüzdesi = tan(açı) × 100. Sıfır noktası bu cihaza özel saklanır.\n\nÖlçmez: yüzeyin düzlüğünü (çukur/tümsek), yalnızca telefonun değdiği noktaların eğimini.",
           "Measures the direction of gravity with the accelerometer (or the gravity sensor). Lying on a surface it shows a two-axis bubble; standing on its edge it shows a single angle. The mode switches by itself.\n\nSlope % = tan(angle) × 100. The zero point is stored for this phone only.\n\nDoes not measure flatness (bumps/dips), only the tilt where the phone touches."),
 "compass": ("Manyetometre ve hareket sensörleriyle telefonun baktığı yönü bulur. Konum izni verilirse dünya manyetik modelinden (WMM) sapma açısı hesaplanır ve gerçek kuzey gösterilir; izin yoksa sapma elle girilebilir.\n\nAlan şiddeti beklenenden çok farklıysa yakında metal ya da mıknatıs vardır; okuma güvenilmez.",
             "Finds the direction the phone points using the magnetometer and motion sensors. With location permission the declination comes from the World Magnetic Model (WMM) and true north is shown; otherwise you can enter it by hand.\n\nIf the field strength is far from the expected value, metal or a magnet is nearby and the reading is unreliable."),
 "magnetometer": ("Manyetik alanı üç eksende ve toplam olarak mikrotesla (µT) cinsinden ölçer. Dünyanın alanı bulunduğunuz yere göre yaklaşık 25–65 µT'dir.\n\nAndroid telefonun kendi mıknatıslığını arka planda düzeltir; bu yüzden değer ara ara küçük sıçramalar yapabilir.",
                  "Measures the magnetic field on three axes and in total, in microtesla (µT). The Earth's field is about 25–65 µT depending on where you are.\n\nAndroid corrects for the phone's own magnetism in the background, so the value may jump slightly now and then."),
 "metal_finder": ("Boş bir noktada ortam alanı taban alınır; tarama sırasında bu tabandan sapma ölçülür. Demir ve çelik (çivi, profil, inşaat demiri, demir boru) alanı bozar ve bulunur. Akım taşıyan kablo da zayıf bir iz bırakabilir.\n\nBakır, alüminyum, plastik boru ve akımsız kablo bulunamaz. Bu araç kesin değildir; elektrik işinden önce kesinlikle güvenlik aracı olarak kullanılmamalıdır.",
                  "The ambient field at an empty spot is taken as the baseline; while scanning, the deviation from it is measured. Iron and steel (nails, studs, rebar, iron pipes) disturb the field and are found. Live cables may leave a weak trace.\n\nCopper, aluminium, plastic pipes and unpowered cables cannot be found. This tool is not definitive and must never be used as a safety tool before electrical work."),
 "barometer": ("Hava basıncını ölçer. Bulunduğunuz yerin yüksekliği girilirse deniz seviyesine indirgenmiş basınç (hava raporlarındaki değer) hesaplanır.\n\nİsteğe bağlı basınç günlüğü açılırsa uygulama yaklaşık 30 dakikada bir tek okuma yapar ve son 48 saati saklar; 3 saatlik değişim basit bir hava eğilimi verir.",
                "Measures air pressure. If you enter your altitude, the sea-level pressure (the value in weather reports) is calculated.\n\nWith the optional pressure log, the app takes one reading about every 30 minutes and keeps the last 48 hours; the 3-hour change gives a simple weather trend."),
 "altimeter": ("Basınç değişiminden yükseklik değişimini hesaplar (≈0,12 hPa ≈ 1 m). Asansörde ya da yürüyüşte bağıl yükseklik için çok iyidir.\n\nHava basıncı gün içinde birkaç hPa değişebilir; bu da onlarca metre kayma demektir. Referansı (burası 0 m, bilinen yükseklik ya da GPS) ara ara yenileyin.",
                "Calculates altitude change from pressure change (≈0.12 hPa ≈ 1 m). Excellent for relative height in lifts or on walks.\n\nAir pressure can change by a few hPa during the day, which means tens of metres of drift. Refresh the reference (here = 0 m, a known altitude, or GPS) now and then."),
 "lux": ("Telefonun ortam ışığı sensörüyle aydınlık düzeyini lüks cinsinden ölçer. Sensör genelde ön kameranın yanındadır; ölçüm yaparken telefonu yüzü ışığa bakacak şekilde, gölge düşürmeden tutun.\n\nSensör ekran parlaklığı için yapılmıştır; doğru sonuç için bilinen bir lüksmetreyle kalibre edin. Ortam ışığı sensörü olmayan telefonlarda değer ön kameranın pozlamasından kabaca hesaplanır.",
         "Measures illuminance in lux with the ambient light sensor. The sensor is usually next to the front camera; hold the phone facing the light without casting a shadow.\n\nThe sensor is made for screen brightness; calibrate it against a known lux meter for accurate results. On phones without an ambient light sensor the value is roughly estimated from the front camera's exposure."),
 "sound_level": ("Mikrofondan gelen sesi IEC 61672 A, C ya da Z ağırlıklandırmasıyla süzer; Hızlı (125 ms) ya da Yavaş (1 s) zaman ağırlıklı seviyeyi, eşdeğer sürekli seviyeyi (Leq) ve en büyük değeri (Lmax) hesaplar.\n\nSes kaydedilmez; yalnızca seviyeler cihazda hesaplanır. Telefon mikrofonu çok yüksek seslerde doyabilir; uygulama bunu fark edince uyarır.",
                 "Filters the microphone signal with IEC 61672 A, C or Z weighting and calculates the Fast (125 ms) or Slow (1 s) time-weighted level, the equivalent continuous level (Leq) and the maximum (Lmax).\n\nNo audio is recorded; only levels are calculated on the phone. The microphone can saturate on very loud sounds; the app warns when it notices."),
 "sensor_test": ("Telefondaki bütün sensörleri listeler. Bir sensöre dokununca canlı ham değerleri ve gerçekte ulaşılan örnekleme hızı görünür.",
                 "Lists every sensor in the phone. Tap a sensor to see its live raw values and the sample rate it actually reaches."),
 "device_report": ("Telefonun hangi donanımlara sahip olduğunu ve bu yüzden hangi araçların çalışacağını gösterir. Sensörlerin üreticisi, en yüksek hızı ve çözünürlüğü listelenir. \"Gürültüyü ölç\" ile telefon masadayken sensörlerin gürültüsü ölçülür.\n\nPDF olarak paylaşılabilir; ikinci el telefon alırken de işe yarar.",
                   "Shows which hardware the phone has and therefore which tools will work. Sensor vendors, maximum rates and resolutions are listed. \"Measure noise\" measures sensor noise while the phone rests on a table.\n\nShareable as PDF; handy when buying a used phone."),
}
